import{_ as a,o as i,c as l,ae as o}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"模版账单导入指南","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/01-template-bill-import-guide.md","filePath":"v1/zh/guide/01-template-bill-import-guide.md"}'),r={name:"v1/zh/guide/01-template-bill-import-guide.md"};function s(e,t,n,h,d,u){return i(),l("div",null,[...t[0]||(t[0]=[o(`<h1 id="模版账单导入指南" tabindex="-1">模版账单导入指南 <a class="header-anchor" href="#模版账单导入指南" aria-label="Permalink to &quot;模版账单导入指南&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>考拉记账支持从外部文件导入账单数据，方便您快速迁移历史账单记录。目前支持以下导入方式：</p><ul><li><strong>模版文件导入</strong>：使用标准格式的 CSV 文件导入</li><li><strong>微信账单导入</strong>：直接导入微信导出的账单文件</li><li><strong>支付宝账单导入</strong>：直接导入支付宝导出的账单文件</li><li>貔貅记账App账单导入：直接导入貔貅app导出的csv格式的账单文件</li><li>iCost记账App账单导入：直接导入iCost App导出的xlsx文件格式的账单文件</li></ul><hr><h2 id="📁-支持的文件格式" tabindex="-1">📁 支持的文件格式 <a class="header-anchor" href="#📁-支持的文件格式" aria-label="Permalink to &quot;📁 支持的文件格式&quot;">​</a></h2><ul><li><strong>CSV 文件</strong>（<code>.csv</code>）：支付宝、貔貅、模版账单</li><li><strong>Excel 文件</strong>（<code>.xlsx</code>、<code>.xls</code>）：微信账单、iCost账单</li></ul><hr><h2 id="🚀-快速开始" tabindex="-1">🚀 快速开始 <a class="header-anchor" href="#🚀-快速开始" aria-label="Permalink to &quot;🚀 快速开始&quot;">​</a></h2><h3 id="步骤-1-进入导入页面" tabindex="-1">步骤 1：进入导入页面 <a class="header-anchor" href="#步骤-1-进入导入页面" aria-label="Permalink to &quot;步骤 1：进入导入页面&quot;">​</a></h3><ol><li>打开考拉记账 App</li><li>点击底部导航栏的 <strong>&quot;设置&quot;</strong> 图标</li><li>在设置页面中找到 <strong>&quot;账单导入&quot;</strong> 选项</li><li>点击进入账单导入页面</li></ol><h3 id="步骤-2-选择导入来源" tabindex="-1">步骤 2：选择导入来源 <a class="header-anchor" href="#步骤-2-选择导入来源" aria-label="Permalink to &quot;步骤 2：选择导入来源&quot;">​</a></h3><p>在导入页面中，您需要选择账单的来源类型：</p><ul><li><strong>模版文件</strong>：适用于标准格式的 CSV 文件</li><li><strong>微信</strong>：适用于微信导出的账单文件</li><li><strong>支付宝</strong>：适用于支付宝导出的账单文件</li><li>貔貅记账：适用于貔貅记账app导出的账单文件</li><li>iCost：适用于iCost app导出的账单文件</li></ul><blockquote><p>⚠️ <strong>重要</strong>：请务必选择正确的导入来源，否则可能导致数据解析失败。</p></blockquote><h3 id="步骤-3-选择文件" tabindex="-1">步骤 3：选择文件 <a class="header-anchor" href="#步骤-3-选择文件" aria-label="Permalink to &quot;步骤 3：选择文件&quot;">​</a></h3><ol><li>点击 <strong>&quot;文件路径&quot;</strong> 选项</li><li>在文件选择器中选择要导入的文件</li><li>确认文件已选择（会显示文件名）</li></ol><blockquote><p>📝 <strong>注意</strong>：</p><ul><li>文件必须保存在设备本地（可通过文件管理器访问）</li><li>确保文件格式正确（CSV 或 xlsx）</li><li>确保文件未损坏</li></ul></blockquote><h3 id="步骤-4-关联账本" tabindex="-1">步骤 4：关联账本 <a class="header-anchor" href="#步骤-4-关联账本" aria-label="Permalink to &quot;步骤 4：关联账本&quot;">​</a></h3><ol><li>点击 <strong>&quot;关联账本&quot;</strong> 选项</li><li>选择要将账单导入到哪个账本</li><li>确认账本选择</li></ol><blockquote><p>💡 <strong>提示</strong>：如果只有一个账本，系统会自动关联到默认账本。</p></blockquote><h3 id="步骤-5-解析文件" tabindex="-1">步骤 5：解析文件 <a class="header-anchor" href="#步骤-5-解析文件" aria-label="Permalink to &quot;步骤 5：解析文件&quot;">​</a></h3><ol><li>点击右上角的 <strong>&quot;解析&quot;</strong> 按钮</li><li>等待系统解析文件（可能需要几秒钟）</li><li>解析成功后，会自动跳转到预览页面</li></ol><blockquote><p>⚠️ <strong>如果解析失败</strong>：</p><ul><li>检查文件格式是否正确</li><li>检查是否选择了正确的导入来源</li><li>检查文件是否损坏</li><li>尝试重新导出文件</li></ul></blockquote><h3 id="步骤-6-预览和编辑" tabindex="-1">步骤 6：预览和编辑 <a class="header-anchor" href="#步骤-6-预览和编辑" aria-label="Permalink to &quot;步骤 6：预览和编辑&quot;">​</a></h3><p>解析成功后，您可以在预览页面中：</p><ul><li><strong>查看所有账单记录</strong>：按日期分组显示</li><li><strong>编辑单条记录</strong>：点击记录可以修改分类、金额、时间等</li><li><strong>删除无效记录</strong>：长按记录可以删除</li><li><strong>批量操作</strong>：可以选择跳过无效记录</li></ul><blockquote><p>📝 <strong>建议</strong>：在导入前，先预览数据，确保数据正确后再导入。</p></blockquote><h3 id="步骤-7-导入数据" tabindex="-1">步骤 7：导入数据 <a class="header-anchor" href="#步骤-7-导入数据" aria-label="Permalink to &quot;步骤 7：导入数据&quot;">​</a></h3><ol><li>在预览页面确认数据无误后</li><li>点击 <strong>&quot;导入&quot;</strong> 按钮</li><li>等待导入完成（可能需要几秒钟）</li><li>导入成功后，会显示导入结果</li></ol><blockquote><p>✅ <strong>导入成功</strong>：所有有效记录已导入到账本中，您可以在账单列表中查看。</p></blockquote><hr><h2 id="📝-模版文件格式说明" tabindex="-1">📝 模版文件格式说明 <a class="header-anchor" href="#📝-模版文件格式说明" aria-label="Permalink to &quot;📝 模版文件格式说明&quot;">​</a></h2><p>如果您想使用模版文件导入，需要按照以下格式准备 CSV 文件：</p><h3 id="csv-文件格式要求" tabindex="-1">CSV 文件格式要求 <a class="header-anchor" href="#csv-文件格式要求" aria-label="Permalink to &quot;CSV 文件格式要求&quot;">​</a></h3><ol><li><strong>文件编码</strong>：支持 UTF-8 或 GBK 编码</li><li><strong>分隔符</strong>：使用逗号（<code>,</code>）分隔</li><li><strong>表头</strong>：第一行必须包含表头</li></ol><h3 id="标准格式示例" tabindex="-1">标准格式示例 <a class="header-anchor" href="#标准格式示例" aria-label="Permalink to &quot;标准格式示例&quot;">​</a></h3><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">日期,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">类型,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">金额,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">分类,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">账户,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">备注,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">标签</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-01,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">支出,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">100.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">餐饮,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">现金,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">午餐,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">工作餐</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-02,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">收入,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">5000.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">工资,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">银行卡,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">月薪,</span></span></code></pre></div><h3 id="字段说明" tabindex="-1">字段说明 <a class="header-anchor" href="#字段说明" aria-label="Permalink to &quot;字段说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>必填</th><th>示例</th></tr></thead><tbody><tr><td>交易日期</td><td>账单日期，格式：yyyy/MM/dd</td><td>✅</td><td>2026/01/01</td></tr><tr><td>交易分类</td><td>支出或收入</td><td>✅</td><td>支出 / 收入</td></tr><tr><td>收支大类</td><td>一级分类名称</td><td>✅</td><td>伙食</td></tr><tr><td>收支小类</td><td>二级分类名称，所属于一级分类的子分类</td><td>✅</td><td>早餐</td></tr><tr><td>流入金额</td><td>账单金额，数字格式，如果“交易分类”为“收入”就在此栏填写</td><td>✅</td><td>100.00</td></tr><tr><td>流出金额</td><td>账单金额，数字格式，如果“交易分类”为“支出”就在此栏填写</td><td>✅</td><td>15</td></tr><tr><td>资金账户</td><td>账户名称，尽量填写app中已存在的账户名称</td><td>✅</td><td>默认账户</td></tr><tr><td>备注</td><td>账单备注</td><td>❌</td><td>午餐</td></tr><tr><td>标签</td><td>标签名称，多个用逗号分隔</td><td>❌</td><td>工作餐,聚餐</td></tr></tbody></table><h3 id="下载模版文件" tabindex="-1">下载模版文件 <a class="header-anchor" href="#下载模版文件" aria-label="Permalink to &quot;下载模版文件&quot;">​</a></h3><ol><li>在导入页面点击 <strong>&quot;下载模版文件&quot;</strong> 按钮</li><li>系统会下载一个示例 CSV 文件</li><li>您可以参考模版文件的格式来准备自己的数据</li></ol><hr><h2 id="⚠️-注意事项" tabindex="-1">⚠️ 注意事项 <a class="header-anchor" href="#⚠️-注意事项" aria-label="Permalink to &quot;⚠️ 注意事项&quot;">​</a></h2><h3 id="_1-数据格式要求" tabindex="-1">1. 数据格式要求 <a class="header-anchor" href="#_1-数据格式要求" aria-label="Permalink to &quot;1. 数据格式要求&quot;">​</a></h3><ul><li><strong>日期格式</strong>：必须为 <code>YYYY/MM/DD</code> 格式（如：2026/01/01）</li><li><strong>金额格式</strong>：必须为数字格式，支持小数点（如：100.00）</li><li><strong>交易分类</strong>：必须为 &quot;支出&quot; 或 &quot;收入&quot;</li><li><strong>分类和账户</strong>：必须在 App 中已存在，否则导入时会自动创建</li></ul><h3 id="_2-数据验证" tabindex="-1">2. 数据验证 <a class="header-anchor" href="#_2-数据验证" aria-label="Permalink to &quot;2. 数据验证&quot;">​</a></h3><p>导入前，系统会自动验证数据：</p><ul><li>✅ <strong>有效记录</strong>：格式正确，可以正常导入</li><li>⚠️ <strong>无效记录</strong>：格式错误，需要修改后才能导入</li><li>❌ <strong>跳过记录</strong>：可以选择跳过无效记录，只导入有效数据</li></ul><h3 id="_3-重复数据处理" tabindex="-1">3. 重复数据处理 <a class="header-anchor" href="#_3-重复数据处理" aria-label="Permalink to &quot;3. 重复数据处理&quot;">​</a></h3><ul><li>建议在导入前先检查是否有重复数据</li></ul><h3 id="_4-大量数据导入" tabindex="-1">4. 大量数据导入 <a class="header-anchor" href="#_4-大量数据导入" aria-label="Permalink to &quot;4. 大量数据导入&quot;">​</a></h3><ul><li>如果数据量很大（超过 1000 条），建议分批导入</li><li>导入过程中请保持 App 在前台运行</li><li>导入完成后，建议手动同步一次数据</li></ul><hr><h2 id="🔧-常见问题" tabindex="-1">🔧 常见问题 <a class="header-anchor" href="#🔧-常见问题" aria-label="Permalink to &quot;🔧 常见问题&quot;">​</a></h2><h3 id="q1-解析失败怎么办" tabindex="-1">Q1：解析失败怎么办？ <a class="header-anchor" href="#q1-解析失败怎么办" aria-label="Permalink to &quot;Q1：解析失败怎么办？&quot;">​</a></h3><p><strong>A：</strong> 请检查以下几点：</p><ol><li>文件格式是否正确（CSV 或 xlsx）</li><li>是否选择了正确的导入来源</li><li>文件是否损坏</li><li>文件编码是否正确（建议使用 UTF-8）</li></ol><h3 id="q2-导入后数据不完整" tabindex="-1">Q2：导入后数据不完整？ <a class="header-anchor" href="#q2-导入后数据不完整" aria-label="Permalink to &quot;Q2：导入后数据不完整？&quot;">​</a></h3><p><strong>A：</strong> 可能的原因：</p><ol><li>部分记录格式错误，被系统跳过</li><li>分类或账户不存在，需要先创建</li><li>建议在预览页面检查无效记录</li></ol><h3 id="q3-可以导入图片吗" tabindex="-1">Q3：可以导入图片吗？ <a class="header-anchor" href="#q3-可以导入图片吗" aria-label="Permalink to &quot;Q3：可以导入图片吗？&quot;">​</a></h3><p><strong>A：</strong> 目前不支持导入图片。</p><h3 id="q4-导入后可以修改吗" tabindex="-1">Q4：导入后可以修改吗？ <a class="header-anchor" href="#q4-导入后可以修改吗" aria-label="Permalink to &quot;Q4：导入后可以修改吗？&quot;">​</a></h3><p><strong>A：</strong> 可以。导入后，您可以在账单列表中编辑或删除任何记录。</p><h3 id="q5-支持批量导入多个文件吗" tabindex="-1">Q5：支持批量导入多个文件吗？ <a class="header-anchor" href="#q5-支持批量导入多个文件吗" aria-label="Permalink to &quot;Q5：支持批量导入多个文件吗？&quot;">​</a></h3><p><strong>A：</strong> 目前不支持。每次只能导入一个文件。如果需要导入多个文件，请逐个导入。</p><hr><h2 id="📚-相关教程" tabindex="-1">📚 相关教程 <a class="header-anchor" href="#📚-相关教程" aria-label="Permalink to &quot;📚 相关教程&quot;">​</a></h2><ul><li><a href="./02-wechat-bill-import-guide">微信账单导入教程</a></li><li><a href="./03-alipay-bill-import-guide">支付宝账单导入教程</a></li><li><a href="./04-multi-ledger-guide">多账本功能说明</a></li></ul><hr><h2 id="💡-提示" tabindex="-1">💡 提示 <a class="header-anchor" href="#💡-提示" aria-label="Permalink to &quot;💡 提示&quot;">​</a></h2><ul><li>导入前建议先备份现有数据</li><li>导入后建议检查数据是否正确</li><li>如有问题，可以通过&quot;问题反馈&quot;功能联系开发者</li></ul><hr><p><strong>最后更新</strong>：2026年1月</p>`,75)])])}const c=a(r,[["render",s]]);export{g as __pageData,c as default};
